%---------1st reaction----------

%data set a1: H2O inlet concentration vs Rate of HCHO formation
%rate with constant MeOH(6%), oxygen(10%) 
%250C 
% rate order of H2O will be determined here
H2O_a1_250 = [1.5961    2.2488    2.4685    2.7851    3.3150];
