ln_R_HCHO_a1_250 = log(R_HCHO_a1_250);

figure ("Name","Reaction Order of H2O (250C)") %[output:437f857e]
scatter(ln_H2O_a1_250,ln_R_HCHO_a1_250,'x','SizeData',100,'Linewidth',2); %[output:437f857e]
xlabel("ln(concentration of H2O)") %[output:437f857e]
ylabel("ln(Rate of HCHO formation)") %[output:437f857e]
hold on %[output:437f857e]
H2O_Trendline = polyfit(ln_H2O_a1_250,ln_R_HCHO_a1_250,1);
y_values_H2O = polyval(H2O_Trendline , ln_H2O_a1_250);
plot(ln_H2O_a1_250, y_values_H2O, 'r-','LineWidth',1.5); %[output:437f857e]
legend('Data Points', 'Linear Fit'); %[output:437f857e]
title("6% MeOH, 10% O2, ln(H2O) vs ln(rate of HCHO) at 250C") %[output:437f857e]
