rate_250 = 10^-3.*[5.2358    6.9431    7.2846    7.0569    7.2087    6.4499    3.5956    5.6612    6.3115    5.9672    6.5792    7.1913    8.8743    8.8743    8.4536    9.6658    7.1342    6.4438    5.9836    7.1342];

