nom2b = alpha*kCH3OH_270*KCH3OH_270*(6/100)*KO2_270.*((o2_conc./100).^0.5);
den2b = (1+KCH3OH_270*(6/100)+KH2O_270*(2.5/100)).*(1+KO2_270.*(o2_conc./100).^0.5);
R_HCHO_LHHW_b2 = nom2b./den2b;

plot(o2_conc,R_HCHO_LHHW_b2,'LineWidth',1.5) %[output:677a651a]
legend(["Simple Power Law Kinetics - Prediction","Experimental Data","LHHM Kinetics - Prediction"]) %[output:677a651a]
xlabel("Concentration of O2") %[output:677a651a]
ylabel("Rate of formation of HCHO") %[output:677a651a]
title("6% MeOH, 2.5% H2O, O2 conc. vs rate of HCHO (270C)") %[output:677a651a]

